function.arguments:
{"script":"(() => {
  // Get all h3 headings (product titles)
  const headings = Array.from(document.querySelectorAll('h3'));
  const products = headings.map(h => {
    const name = h.textContent.trim();
    // Get sibling container to find variants and prices
    const container = h.parentElement;
    const variants = Array.from(container.querySelectorAll('slick')).map(s => {
      const items = Array.from(s.querySelectorAll('a, .product-title, [class*="title"], [class*="variant"]'));
      return items.map(i => i.textContent.trim()).filter(t => t).slice(0, 5);
    });
    return { name, variants: variants.flat().slice(0, 5) };
  });
  return products;
})()"}

